// src/App.js
import { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate, Link } from "react-router-dom";
import axios from "axios";

import sorsuLogo from "./assets/sorsu-logo.png";

import AdminPanel from "./components/AdminPanel";
import AdminCodesPanel from "./components/AdminCodesPanel";
import AdminAnonymousResults from "./components/AdminAnonymousResults";
import AdminFeedback from "./pages/AdminFeedback";
import AuthPage from "./components/AuthPage";
import VoterDashboard from "./components/VoterDashboard";
import CandidatesPage from "./components/CandidatesPage";

const API_URL = "http://localhost:5000";

function App() {
  const [candidates, setCandidates] = useState([]);
  const [showAnonymous, setShowAnonymous] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");
  const [hasVoted, setHasVoted] = useState(false);

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token"),
    role: localStorage.getItem("role"),
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    partylist: "",
    yearLevel: "",
    block: "",
    course: "",
    description: "",
    image: null,
  });

  const theme = {
    background: "#f1f5f9",
    navbar: "#ffffff",
    card: "#ffffff",
    text: "#0f172a",
    button: "#6366f1",
  };

  // =========================
  // FETCH CANDIDATES
  // =========================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
    const interval = setInterval(fetchCandidates, 10000);
    return () => clearInterval(interval);
  }, []);

  // =========================
  // CHECK IF USER VOTED
  // =========================
  useEffect(() => {
    if (!auth.token) return;
    axios.get(`${API_URL}/api/vote/my`, { headers: { Authorization: `Bearer ${auth.token}` } })
      .then(res => setHasVoted(res.data.length > 0))
      .catch(err => console.error("Vote fetch error:", err));
  }, [auth.token]);

  // =========================
  // LOGOUT
  // =========================
  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  // =========================
  // SAVE CANDIDATE
  // =========================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      Object.entries(candidateForm).forEach(([key, value]) => {
        if (value) formData.append(key, value);
      });

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}`, "Content-Type": "multipart/form-data" },
        });
        setMessage("Candidate updated successfully.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}`, "Content-Type": "multipart/form-data" },
        });
        setMessage("Candidate added successfully.");
      }

      setCandidateForm({ firstName:"", lastName:"", candidacy:"", partylist:"", yearLevel:"", block:"", course:"", description:"", image:null });
      setEditId(null);
      fetchCandidates();
      setTimeout(() => setMessage(""), 3000);
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  // =========================
  // DELETE CANDIDATE
  // =========================
  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, { headers: { Authorization: `Bearer ${auth.token}` } });
      setMessage("Candidate deleted.");
      fetchCandidates();
      setTimeout(() => setMessage(""), 3000);
    } catch {
      setMessage("Delete failed.");
    }
  };

  const totalVotes = candidates.reduce((sum, c) => sum + (c.votes || 0), 0);

  // =========================
  // RENDER
  // =========================
  return (
    <Router>
      {!auth.token && (
        <Routes>
          <Route path="*" element={<AuthPage setAuth={setAuth} />} />
        </Routes>
      )}

      {auth.token && (
        <div style={{ minHeight: "100vh", backgroundColor: theme.background, color: theme.text }}>
          {/* NAVBAR */}
          <Navbar auth={auth} hasVoted={hasVoted} theme={theme} showAnonymous={showAnonymous} setShowAnonymous={setShowAnonymous} electionClosed={electionClosed} setElectionClosed={setElectionClosed} handleLogout={handleLogout} />

          {/* CONTENT */}
          <div style={{ maxWidth: "1200px", margin: "40px auto", padding: "0 20px" }}>
            <Routes>
              {/* Voter Pages */}
              {(auth.role === "user" || auth.role === "voter") && (
                <>
                  <Route path="/dashboard" element={<VoterDashboard auth={auth} electionClosed={electionClosed} />} />
                  <Route path="/candidates" element={<CandidatesPage auth={auth} />} />
                  <Route path="/my-votes" element={<VoterDashboard auth={auth} />} />
                  <Route path="*" element={<Navigate to="/dashboard" />} />
                </>
              )}

              {/* Admin Pages */}
              {auth.role === "admin" && (
                <>
                  <Route path="/admin" element={<AdminPanel candidateForm={candidateForm} setCandidateForm={setCandidateForm} onSave={handleSaveCandidate} editId={editId} setEditId={setEditId} onDelete={handleDeleteCandidate} candidates={candidates} theme={theme} totalVotes={totalVotes} />} />
                  <Route path="/admin-codes" element={<AdminCodesPanel />} />
                  <Route path="/admin-anonymous-results" element={<AdminAnonymousResults theme={theme} />} />
                  <Route path="/admin-feedback" element={<AdminFeedback />} />
                  <Route path="*" element={<Navigate to="/admin" />} />
                </>
              )}
            </Routes>
          </div>
        </div>
      )}
    </Router>
  );
}

// =========================
// NAVBAR COMPONENT
// =========================
const Navbar = ({ auth, hasVoted, theme, showAnonymous, setShowAnonymous, electionClosed, setElectionClosed, handleLogout }) => {
  return (
    <div style={navbarStyle(theme)}>
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <img src={sorsuLogo} alt="SorSU Logo" style={{ height: 50 }} />
        <div>
          <h1 style={{ margin: 0 }}>SorSU Online Voting</h1>
          <small style={{ opacity: 0.6 }}>Official Student Election Portal</small>
        </div>
      </div>

      <div style={{ display: "flex", gap: 12 }}>
        {(auth.role === "user" || auth.role === "voter") && (
          <>
            <Link to="/dashboard" style={modernButton(theme)}>Dashboard</Link>
            <Link to="/candidates" style={modernButton(theme)}>Candidates</Link>
            {hasVoted && <Link to="/my-votes" style={modernButton(theme)}>My Ballot</Link>}
          </>
        )}

        {auth.role === "admin" && (
          <>
            <Link to="/admin" style={modernButton(theme)}>Live Vote Monitor</Link>
            <Link to="/admin-anonymous-results" style={modernButton(theme)}>Anonymous Results</Link>
            <Link to="/admin-codes" style={modernButton(theme)}>Voter Codes</Link>
            <Link to="/admin-feedback" style={modernButton(theme)}>Feedback</Link>

            <button
              onClick={() => setElectionClosed(!electionClosed)}
              style={{ ...modernButton(theme), backgroundColor: electionClosed ? "#10b981" : "#ef4444" }}
            >
              {electionClosed ? "Open Election" : "Close Election"}
            </button>
          </>
        )}

        <button onClick={handleLogout} style={{ ...modernButton(theme), backgroundColor: "#ef4444" }}>
          Logout
        </button>
      </div>
    </div>
  );
};

// =========================
// STYLES
// =========================
const modernButton = (theme) => ({
  padding: "8px 14px",
  backgroundColor: theme.button,
  color: "#fff",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  fontWeight: "500",
  fontSize: "14px",
